export enum MealType {
  Breakfast = 'breakfast',
  Lunch = 'lunch',
  Dinner = 'dinner',
  Snack = 'snack',
}

export enum DietTag {
  /** No meat and fish, but dairy and eggs. */
  Vegetarian = 'vegetarian',
  /** No animal products at all. */
  Vegan = 'vegan',
  /** Vegetarian plus fish and seafood. */
  Pescatarian = 'pescatarian',
  GlutenFree = 'gluten_free',
  DairyFree = 'dairy_free',
  HighProtein = 'high_protein',
  LowCarb = 'low_carb',
}

export enum RecipeSource {
  /** `data/seed/recipes.json`, `source_id` is a slug. */
  Seed = 'seed',
  Manual = 'manual',
  /** Generated by the AI flow (next stage). */
  Llm = 'llm',
}

export const RECIPE_NAME_MAX_LENGTH = 255;
export const INGREDIENT_NOTES_MAX_LENGTH = 500;
